/**
 * AllLevelsCompletedNode is a pseudo-dialog shown when all game levels have been completed.
 *
 * @author Jonathan Olson
 */
import { string_vegas_youCompletedAllLevels_StringProperty } from './strings/youCompletedAllLevels.js';
import { string_vegas_done_StringProperty } from './strings/done.js';
import '../../globals.js';
import optionize from '../../phet-core/js/optionize.js';
import FaceNode from '../../scenery-phet/js/FaceNode.js';
import PhetFont from '../../scenery-phet/js/PhetFont.js';
import VBox from '../../scenery/js/layout/nodes/VBox.js';
import Node from '../../scenery/js/nodes/Node.js';
import RichText from '../../scenery/js/nodes/RichText.js';
import Text from '../../scenery/js/nodes/Text.js';
import RectangularPushButton from '../../sun/js/buttons/RectangularPushButton.js';
import Panel from '../../sun/js/Panel.js';
import vegas from './vegas.js';
export default class AllLevelsCompletedNode extends Node {
    /**
     * @param listener function that gets called when 'next' button is pressed
     * @param providedOptions
     */
    constructor(listener, providedOptions) {
        super();
        const options = optionize()({
            // SelfOptions
            faceDiameter: 160,
            maxTextWidth: 300
        }, providedOptions);
        // create the smiley face
        const faceNode = new FaceNode(options.faceDiameter);
        // create the dialog text
        const textMessage = new RichText(string_vegas_youCompletedAllLevels_StringProperty, {
            font: new PhetFont(25),
            lineWrap: 300,
            maxWidth: options.maxTextWidth,
            maxHeight: 300
        });
        // create the button
        const button = new RectangularPushButton({
            content: new Text(string_vegas_done_StringProperty, {
                font: new PhetFont(30),
                maxWidth: options.maxTextWidth
            }),
            listener: listener,
            baseColor: 'yellow'
        });
        // add the main background panel
        this.addChild(new Panel(new VBox({ children: [faceNode, textMessage, button], spacing: 20 }), { xMargin: 50, yMargin: 20 }));
        this.mutate(options);
    }
}
vegas.register('AllLevelsCompletedNode', AllLevelsCompletedNode);
